<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// === GEOMETRY SPEC ===
// Front carbon: SphereGeometry(0.35,24,24) #3a3a3a at model-local (0,0,0.75)
// Rear carbon: SphereGeometry(0.35,24,24) #3a3a3a at model-local (0,0,-0.75)
// C-C bond: CylinderGeometry(0.06,0.06,1.5,12) #c0c0c0 along Z
// Front C-H bonds ×3: CylinderGeometry(0.06,0.06,1.1,8) #c0c0c0 at az 90,210,330 in XY at z=0.75
// Front H spheres ×3: SphereGeometry(0.22,16,16) #2faa44
// Rear C-H bonds ×3: CylinderGeometry(0.06,0.06,1.1,8) #c0c0c0 at az 150,270,30 in XY at z=-0.75
// Rear H spheres ×3: SphereGeometry(0.22,16,16) #cc3333
// Newman circle: LineLoop 64pts r=0.8
// Newman dot: CircleGeometry(0.07,16) #222
// Newman front bonds ×3: Line r=0→0.95 at az 90,210,330 (thick)
// Newman rear bonds ×3: Line r=0.8→1.3 at az 150,270,30 (thin, rotate with slider)
// Braces ×3: Line 24pts arc r≈1.25 at pair angles
// Arrow: Line + ConeGeometry(0.08,0.2) between Newman and model
// Labels: H (green/magenta), 4.0 kJ/mol ×3, caption ×2, arrow label

const DEG = Math.PI / 180;
const FRONT_AZ = [90, 210, 330]; // degrees
const REAR_AZ_BASE = [150, 270, 30]; // front + 60

// ── Model group ──
const modelGroup = new THREE.Group();
modelGroup.position.set(1.5, 0, 0);
scene.add(modelGroup);

const frontGroup = new THREE.Group();
const rearGroup = new THREE.Group();
modelGroup.add(frontGroup, rearGroup);

// C-C bond
const ccBond = new THREE.Mesh(
  new THREE.CylinderGeometry(0.06, 0.06, 1.5, 12),
  new THREE.MeshBasicMaterial({ color: 0xc0c0c0 })
);
modelGroup.add(ccBond);

// Front carbon
const frontC = new THREE.Mesh(
  new THREE.SphereGeometry(0.35, 24, 24),
  new THREE.MeshBasicMaterial({ color: 0x3a3a3a })
);
frontC.position.set(0, 0, 0.75);
frontGroup.add(frontC);

// Rear carbon
const rearC = new THREE.Mesh(
  new THREE.SphereGeometry(0.35, 24, 24),
  new THREE.MeshBasicMaterial({ color: 0x3a3a3a })
);
rearC.position.set(0, 0, -0.75);
rearGroup.add(rearC);

function createBondBetween(start, end, radius, color) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 8),
    new THREE.MeshBasicMaterial({ color })
  );
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  const q = new THREE.Quaternion().setFromUnitVectors(
    new THREE.Vector3(0, 1, 0), dir.normalize()
  );
  mesh.quaternion.copy(q);
  return mesh;
}

// Front C-H bonds and H spheres
const frontHSpheres = [];
const frontBondLen = 1.1;
FRONT_AZ.forEach((az) => {
  const rad = az * DEG;
  const start = new THREE.Vector3(0, 0, 0.75);
  const end = new THREE.Vector3(Math.cos(rad) * frontBondLen, Math.sin(rad) * frontBondLen, 0.75);
  frontGroup.add(createBondBetween(start, end, 0.06, 0xc0c0c0));
  const h = new THREE.Mesh(
    new THREE.SphereGeometry(0.22, 16, 16),
    new THREE.MeshBasicMaterial({ color: 0x2faa44 })
  );
  h.position.copy(end);
  frontGroup.add(h);
  frontHSpheres.push(h);
});

// Rear C-H bonds and H spheres (in rearGroup, rotates with slider)
const rearHSpheres = [];
REAR_AZ_BASE.forEach((az) => {
  const rad = az * DEG;
  const start = new THREE.Vector3(0, 0, -0.75);
  const end = new THREE.Vector3(Math.cos(rad) * frontBondLen, Math.sin(rad) * frontBondLen, -0.75);
  rearGroup.add(createBondBetween(start, end, 0.06, 0xc0c0c0));
  const h = new THREE.Mesh(
    new THREE.SphereGeometry(0.22, 16, 16),
    new THREE.MeshBasicMaterial({ color: 0xcc3333 })
  );
  h.position.copy(end);
  rearGroup.add(h);
  rearHSpheres.push(h);
});

// ── Newman projection group ──
const newmanGroup = new THREE.Group();
newmanGroup.position.set(-2.5, 0, 0);
scene.add(newmanGroup);

// Outer circle (rear carbon)
const circlePts = [];
for (let i = 0; i <= 64; i++) {
  const a = (i / 64) * Math.PI * 2;
  circlePts.push(new THREE.Vector3(Math.cos(a) * 0.8, Math.sin(a) * 0.8, 0));
}
const circleLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(circlePts),
  new THREE.LineBasicMaterial({ color: 0x222222 })
);
newmanGroup.add(circleLine);

// Center dot (front carbon)
const dotMesh = new THREE.Mesh(
  new THREE.CircleGeometry(0.07, 16),
  new THREE.MeshBasicMaterial({ color: 0x222222 })
);
newmanGroup.add(dotMesh);

// Front bond lines (thick)
const newmanFrontLines = [];
FRONT_AZ.forEach((az) => {
  const rad = az * DEG;
  const pts = [
    new THREE.Vector3(0, 0, 0.001),
    new THREE.Vector3(Math.cos(rad) * 0.95, Math.sin(rad) * 0.95, 0.001)
  ];
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x222222, linewidth: 3 })
  );
  newmanGroup.add(line);
  newmanFrontLines.push(line);
});

// Rear bond lines (thin, in a sub-group that rotates)
const newmanRearGroup = new THREE.Group();
newmanGroup.add(newmanRearGroup);
const newmanRearLines = [];
REAR_AZ_BASE.forEach((az) => {
  const rad = az * DEG;
  const pts = [
    new THREE.Vector3(Math.cos(rad) * 0.8, Math.sin(rad) * 0.8, -0.001),
    new THREE.Vector3(Math.cos(rad) * 1.3, Math.sin(rad) * 1.3, -0.001)
  ];
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x222222 })
  );
  newmanRearGroup.add(line);
  newmanRearLines.push(line);
});

// ── Curly braces ──
const braceLines = [];
const braceMats = [];
FRONT_AZ.forEach((az, idx) => {
  const rad = az * DEG;
  const pts = [];
  const N = 24;
  const span = 28 * DEG;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const angle = rad + (t - 0.5) * span;
    const r = 1.25 + 0.18 * Math.sin(Math.PI * t);
    pts.push(new THREE.Vector3(Math.cos(angle) * r, Math.sin(angle) * r, 0.002));
  }
  const mat = new THREE.LineBasicMaterial({ color: 0x222222, transparent: true, opacity: 0 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  newmanGroup.add(line);
  braceLines.push(line);
  braceMats.push(mat);
});

// ── Arrow between views ──
const arrowLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-1.2, 0.6, 0),
    new THREE.Vector3(0.2, 0.6, 0)
  ]),
  new THREE.LineBasicMaterial({ color: 0x222222 })
);
scene.add(arrowLine);
const arrowHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.08, 0.2, 8),
  new THREE.MeshBasicMaterial({ color: 0x222222 })
);
arrowHead.position.set(0.3, 0.6, 0);
arrowHead.rotation.z = -Math.PI / 2;
scene.add(arrowHead);

// ── Labels ──
const newmanFrontHLabels = [];
const newmanRearHLabels = [];

FRONT_AZ.forEach((az) => {
  const rad = az * DEG;
  const pos = new THREE.Vector3(Math.cos(rad) * 1.1, Math.sin(rad) * 1.1, 0);
  const entry = addLabel('<span style="color:#2faa44;font-weight:bold">H</span>', pos, { fontSize: '14px' });
  newmanFrontHLabels.push(entry);
});

REAR_AZ_BASE.forEach((az) => {
  const rad = az * DEG;
  const pos = new THREE.Vector3(Math.cos(rad) * 1.45, Math.sin(rad) * 1.45, 0);
  const entry = addLabel('<span style="color:#cc22aa;font-weight:bold">H</span>', pos, { fontSize: '14px' });
  newmanRearHLabels.push(entry);
});

// 4.0 kJ/mol labels
const kjLabels = [];
FRONT_AZ.forEach((az) => {
  const rad = az * DEG;
  const pos = new THREE.Vector3(Math.cos(rad) * 1.7, Math.sin(rad) * 1.7, 0);
  const entry = addLabel('4.0 kJ/mol', pos, { fontSize: '11px', color: '#222' });
  kjLabels.push(entry);
});

// Arrow label
addLabel('Rotate rear<br>carbon 60°', new THREE.Vector3(-0.5, 1.0, 0), { fontSize: '12px' });

// Captions
const capStaggered = addLabel('<b>Ethane—staggered<br>conformation</b>', new THREE.Vector3(0, -2.2, 0), { fontSize: '14px' });
const capEclipsed = addLabel('<b>Ethane—eclipsed<br>conformation</b>', new THREE.Vector3(0, -2.2, 0), { fontSize: '14px' });
capEclipsed.div.style.display = 'none';

// ── State ─
let highlightedPair = -1;
let currentDihedral = 0;

const slider = document.getElementById('dihedral');
const dihedralVal = document.getElementById('dihedralVal');

function updateDihedral(val) {
  currentDihedral = parseFloat(val);
  dihedralVal.textContent = Math.round(currentDihedral) + '°';

  // Rotate rear group about Z (bond axis)
  rearGroup.rotation.z = -currentDihedral * DEG;
  newmanRearGroup.rotation.z = -currentDihedral * DEG;

  // Brace opacity
  const braceOpacity = Math.max(0, Math.min(1, (currentDihedral - 30) / 30));
  braceMats.forEach((mat, i) => {
    mat.opacity = (i === highlightedPair) ? 1 : braceOpacity;
  });

  // KJ label visibility
  kjLabels.forEach((entry, i) => {
    const vis = (i === highlightedPair) ? '' : (braceOpacity > 0.05 ? '' : 'none');
    entry.div.style.display = vis;
    entry.div.style.opacity = (i === highlightedPair) ? 1 : braceOpacity;
  });

  // Caption toggle
  if (currentDihedral < 30) {
    capStaggered.div.style.display = '';
    capEclipsed.div.style.display = 'none';
  } else {
    capStaggered.div.style.display = 'none';
    capEclipsed.div.style.display = '';
  }

  // Emissive highlight
  frontHSpheres.forEach((s, i) => {
    s.material.color.setHex(i === highlightedPair ? 0x66ff88 : 0x2faa44);
  });
  rearHSpheres.forEach((s, i) => {
    s.material.color.setHex(i === highlightedPair ? 0xff6666 : 0xcc3333);
  });
}

slider.addEventListener('input', () => updateDihedral(slider.value));
updateDihedral(0);

// ── Click interaction for pair highlighting ──
const allHSpheres = [...frontHSpheres, ...rearHSpheres];
allHSpheres.forEach((s, i) => {
  const pairIdx = i % 3;
  registerInteractive(s, {
    title: `H–H eclipsing pair ${pairIdx + 1}`,
    body: `This pair contributes 4.0 kJ/mol to the ~12 kJ/mol torsional barrier. Click to highlight.`,
    tooltip: 'Click to highlight this eclipsing pair',
    onClick: () => {
      highlightedPair = (highlightedPair === pairIdx) ? -1 : pairIdx;
      updateDihedral(currentDihedral);
    }
  });
});

// ── Demo steps ──
let _tweenId = null;
function goToStep(idx) {
  const targets = [0, 30, 60];
  const target = targets[idx];
  const start = parseFloat(slider.value);
  const duration = 800;
  const t0 = performance.now();
  if (_tweenId) cancelAnimationFrame(_tweenId);
  function tick() {
    const t = Math.min(1, (performance.now() - t0) / duration);
    const e = t * t * (3 - 2 * t);
    const v = start + (target - start) * e;
    slider.value = v;
    updateDihedral(v);
    if (t < 1) _tweenId = requestAnimationFrame(tick);
  }
  tick();
}
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));

// ── Billboard Newman group + update label positions ──
const _tmpV = new THREE.Vector3();
function updateNewmanLabels() {
  newmanGroup.quaternion.copy(camera.quaternion);

  newmanFrontHLabels.forEach((entry, i) => {
    const rad = FRONT_AZ[i] * DEG;
    _tmpV.set(Math.cos(rad) * 1.1, Math.sin(rad) * 1.1, 0);
    newmanGroup.localToWorld(_tmpV);
    entry.pos.copy(_tmpV);
  });

  newmanRearHLabels.forEach((entry, i) => {
    const az = REAR_AZ_BASE[i] - currentDihedral;
    const rad = az * DEG;
    _tmpV.set(Math.cos(rad) * 1.45, Math.sin(rad) * 1.45, 0);
    newmanGroup.localToWorld(_tmpV);
    entry.pos.copy(_tmpV);
  });

  kjLabels.forEach((entry, i) => {
