// @FIGURE_CODE_BEGIN
// === GEOMETRY SPEC ===
// Staggered Newman: circle r=0.55, dot r=0.06, front bonds 90/210/330 len 0.7, rear bonds 150/270/30 from r=0.55 to r=0.85
// Staggered 3D model: C spheres r=0.18, H spheres r=0.13, bonds cyl r=0.03, at x=-2.2
// Arrow: line + cone at x=-0.3 to x=0.3, y=0.5
// Eclipsed Newman: circle r=0.55, dot r=0.06, front bonds 90/210/330, rear bonds same angles offset +4deg
// Eclipsed 3D model: same as staggered but rear at same angles, at x=3.2
// Curly braces: arcs between eclipsed pairs with 4.0 kJ/mol labels
// Interactive Newman: small Newman at bottom-center that rotates with slider
// Captions: below each panel pair

const DEG = Math.PI / 180;
const FRONT_AZ = [90, 210, 330];
const REAR_AZ_STAG = [150, 270, 30];
const REAR_AZ_ECL = [94, 214, 334]; // slightly offset for visibility

// ── Helper: create bond cylinder between two points ──
function makeBond(start, end, radius, color) {
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 8),
    new THREE.MeshBasicMaterial({ color })
  );
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

// ── Helper: create Newman projection group ──
function createNewman(frontAz, rearAz, scale = 1) {
  const g = new THREE.Group();
  // Circle
  const cPts = [];
  for (let i = 0; i <= 64; i++) {
    const a = (i / 64) * Math.PI * 2;
    cPts.push(new THREE.Vector3(Math.cos(a) * 0.55 * scale, Math.sin(a) * 0.55 * scale, 0));
  }
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(cPts), new THREE.LineBasicMaterial({ color: 0x222222 })));
  // Dot
  const dot = new THREE.Mesh(new THREE.CircleGeometry(0.06 * scale, 16), new THREE.MeshBasicMaterial({ color: 0x222222 }));
  g.add(dot);
  // Front bonds
  frontAz.forEach(az => {
    const r = az * DEG;
    const pts = [new THREE.Vector3(0, 0, 0.001), new THREE.Vector3(Math.cos(r) * 0.7 * scale, Math.sin(r) * 0.7 * scale, 0.001)];
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x222222 })));
  });
  // Rear bonds
  rearAz.forEach(az => {
    const r = az * DEG;
    const pts = [new THREE.Vector3(Math.cos(r) * 0.55 * scale, Math.sin(r) * 0.55 * scale, -0.001), new THREE.Vector3(Math.cos(r) * 0.85 * scale, Math.sin(r) * 0.85 * scale, -0.001)];
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x222222 })));
  });
  return g;
}

// ── Helper: create 3D ball-and-stick model ──
function createModel3D(rearAz, scale = 0.55) {
  const g = new THREE.Group();
  const bondLen = 0.7 * scale;
  // C-C bond along Z
  const cc = makeBond(new THREE.Vector3(0, 0, -0.4 * scale), new THREE.Vector3(0, 0, 0.4 * scale), 0.035 * scale, 0x888888);
  g.add(cc);
  // Front carbon
  const fc = new THREE.Mesh(new THREE.SphereGeometry(0.18 * scale, 16, 16), new THREE.MeshBasicMaterial({ color: 0x3a3a3a }));
  fc.position.set(0, 0, 0.4 * scale);
  g.add(fc);
  // Rear carbon
  const rc = new THREE.Mesh(new THREE.SphereGeometry(0.18 * scale, 16, 16), new THREE.MeshBasicMaterial({ color: 0x3a3a3a }));
  rc.position.set(0, 0, -0.4 * scale);
  g.add(rc);
  // Front H
  FRONT_AZ.forEach(az => {
    const r = az * DEG;
    const end = new THREE.Vector3(Math.cos(r) * bondLen, Math.sin(r) * bondLen, 0.4 * scale);
    const start = new THREE.Vector3(0, 0, 0.4 * scale);
    g.add(makeBond(start, end, 0.03 * scale, 0xaaaaaa));
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.13 * scale, 12, 12), new THREE.MeshBasicMaterial({ color: 0x2faa44 }));
    h.position.copy(end);
    g.add(h);
  });
  // Rear H
  rearAz.forEach(az => {
    const r = az * DEG;
    const end = new THREE.Vector3(Math.cos(r) * bondLen, Math.sin(r) * bondLen, -0.4 * scale);
    const start = new THREE.Vector3(0, 0, -0.4 * scale);
    g.add(makeBond(start, end, 0.03 * scale, 0xaaaaaa));
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.13 * scale, 12, 12), new THREE.MeshBasicMaterial({ color: 0xcc3333 }));
    h.position.copy(end);
    g.add(h);
  });
  return g;
}

// ── Staggered panel (left) ──
const stagNewman = createNewman(FRONT_AZ, REAR_AZ_STAG);
stagNewman.position.set(-3.8, 0.3, 0);
scene.add(stagNewman);

const stagModel = createModel3D(REAR_AZ_STAG);
stagModel.position.set(-2.4, 0.3, 0);
scene.add(stagModel);

// ── Arrow ──
const arrowPts = [new THREE.Vector3(-1.5, 0.5, 0), new THREE.Vector3(-0.5, 0.5, 0)];
scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(arrowPts), new THREE.LineBasicMaterial({ color: 0x222222 })));
const arrowHead = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.15, 8), new THREE.MeshBasicMaterial({ color: 0x222222 }));
arrowHead.position.set(-0.42, 0.5, 0);
arrowHead.rotation.z = -Math.PI / 2;
scene.add(arrowHead);

// ── Eclipsed panel (right) ──
const eclNewman = createNewman(FRONT_AZ, REAR_AZ_ECL);
eclNewman.position.set(0.8, 0.3, 0);
scene.add(eclNewman);

const eclModel = createModel3D(REAR_AZ_ECL);
eclModel.position.set(2.2, 0.3, 0);
scene.add(eclModel);

// ── Curly braces on eclipsed Newman ──
function createBrace(centerAngle, radius, span, group) {
  const pts = [];
  const N = 20;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const angle = centerAngle + (t - 0.5) * span;
    const r = radius + 0.12 * Math.sin(Math.PI * t);
    pts.push(new THREE.Vector3(Math.cos(angle) * r, Math.sin(angle) * r, 0.002));
  }
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x222222 }));
  group.add(line);
  return line;
}

FRONT_AZ.forEach(az => {
  const rad = az * DEG;
  createBrace(rad, 0.95, 0.45, eclNewman);
});

// ── Interactive Newman (bottom center) ──
const interNewmanGroup = new THREE.Group();
interNewmanGroup.position.set(-0.5, -1.5, 0);
scene.add(interNewmanGroup);

// Circle + dot for interactive
const iCirclePts = [];
for (let i = 0; i <= 64; i++) {
  const a = (i / 64) * Math.PI * 2;
  iCirclePts.push(new THREE.Vector3(Math.cos(a) * 0.4, Math.sin(a) * 0.4, 0));
}
interNewmanGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(iCirclePts), new THREE.LineBasicMaterial({ color: 0x444444 })));
interNewmanGroup.add(new THREE.Mesh(new THREE.CircleGeometry(0.05, 12), new THREE.MeshBasicMaterial({ color: 0x444444 })));

// Front bonds (static)
FRONT_AZ.forEach(az => {
  const r = az * DEG;
  const pts = [new THREE.Vector3(0, 0, 0.001), new THREE.Vector3(Math.cos(r) * 0.52, Math.sin(r) * 0.52, 0.001)];
  interNewmanGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x444444 })));
});

// Rear bonds (rotatable)
const interRearGroup = new THREE.Group();
interNewmanGroup.add(interRearGroup);
REAR_AZ_STAG.forEach(az => {
  const r = az * DEG;
  const pts = [new THREE.Vector3(Math.cos(r) * 0.4, Math.sin(r) * 0.4, -0.001), new THREE.Vector3(Math.cos(r) * 0.62, Math.sin(r) * 0.62, -0.001)];
  interRearGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x444444 })));
});

// ── Labels ──
// Staggered Newman H labels
FRONT_AZ.forEach(az => {
  const r = az * DEG;
  const pos = new THREE.Vector3(-3.8 + Math.cos(r) * 0.82, 0.3 + Math.sin(r) * 0.82, 0);
  addLabel('<span style="color:#2faa44;font-weight:bold">H</span>', pos, { fontSize: '12px' });
});
REAR_AZ_STAG.forEach(az => {
  const r = az * DEG;
  const pos = new THREE.Vector3(-3.8 + Math.cos(r) * 1.0, 0.3 + Math.sin(r) * 1.0, 0);
  addLabel('<span style="color:#cc22aa;font-weight:bold">H</span>', pos, { fontSize: '12px' });
});

// Eclipsed Newman H labels (front)
FRONT_AZ.forEach(az => {
  const r = az * DEG;
  const pos = new THREE.Vector3(0.8 + Math.cos(r) * 0.82, 0.3 + Math.sin(r) * 0.82, 0);
  addLabel('<span style="color:#2faa44;font-weight:bold">H</span>', pos, { fontSize: '12px' });
});
// Eclipsed Newman H labels (rear, slightly offset)
REAR_AZ_ECL.forEach(az => {
  const r = az * DEG;
  const pos = new THREE.Vector3(0.8 + Math.cos(r) * 1.0, 0.3 + Math.sin(r) * 1.0, 0);
  addLabel('<span style="color:#cc22aa;font-weight:bold">H</span>', pos, { fontSize: '12px' });
});

// 4.0 kJ/mol labels on eclipsed
FRONT_AZ.forEach(az => {
  const r = az * DEG;
  const pos = new THREE.Vector3(0.8 + Math.cos(r) * 1.35, 0.3 + Math.sin(r) * 1.35, 0);
  addLabel('4.0 kJ/mol', pos, { fontSize: '10px', color: '#222' });
});

// Arrow label
addLabel('Rotate rear<br>carbon 60°', new THREE.Vector3(-1.0, 0.85, 0), { fontSize: '11px' });

// Captions
addLabel('<b>Ethane—staggered<br>conformation</b>', new THREE.Vector3(-3.1, -1.3, 0), { fontSize: '13px' });
addLabel('<b>Ethane—eclipsed<br>conformation</b>', new THREE.Vector3(1.5, -1.3, 0), { fontSize: '13px' });

// Interactive label
addLabel('<i>Interactive:</i>', new THREE.Vector3(-0.5, -2.2, 0), { fontSize: '10px', color: '#666' });

// ── Interactive slider ──
let currentDihedral = 60;
const slider = document.getElementById('dihedral');
const dihedralVal = document.getElementById('dihedralVal');

function updateDihedral(val) {
  currentDihedral = parseFloat(val);
  dihedralVal.textContent = Math.round(currentDihedral) + '°';
  interRearGroup.rotation.z = -currentDihedral * DEG;
}

slider.addEventListener('input', () => updateDihedral(slider.value));
updateDihedral(60);

// ── Step buttons ──
let _tweenId = null;
function goToStep(idx) {
  const targets = [0, 30, 60];
  const target = targets[idx];
  const start = parseFloat(slider.value);
  const duration = 600;
  const t0 = performance.now();
  if (_tweenId) cancelAnimationFrame(_tweenId);
  function tick() {
    const t = Math.min(1, (performance.now() - t0) / duration);
    const e = t * t * (3 - 2 * t);
    const v = start + (target - start) * e;
    slider.value = v;
    updateDihedral(v);
    if (t < 1) _tweenId = requestAnimationFrame(tick);
  }
  tick();
}
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));

// ── Register interactive elements ──
registerInteractive(stagModel, {
  title: 'Staggered conformation',
  body: 'In the staggered conformation, the C-H bonds on adjacent carbons are 60° apart (dihedral angle). This minimizes electron repulsion and is the energy minimum.',
  tooltip: 'Staggered ethane - energy minimum'
});
registerInteractive(eclModel, {
  title: 'Eclipsed conformation',
  body: 'In the eclipsed conformation, the C-H bonds on adjacent carbons align (0° dihedral). This maximizes torsional strain (~12 kJ/mol total, 4.0 kJ/mol per H-H pair).',
  tooltip: 'Eclipsed ethane - energy maximum'
});

// ── Camera ──
setCameraView({
  projection: 'perspective',
  azimuthDeg: 80,
  elevationDeg: 12,
  heightFraction: 0.72,
  target: [-0.5, 0, 0]
});
// @FIGURE_CODE_END

